def is_good_2d(m):
    # List of 2-digit good numbers provided in notes.md
    good_2d = {12, 13, 14, 15, 16, 17, 18, 19, 21, 24, 25, 26, 28, 31, 32, 35, 36, 39, 41, 42, 45, 48, 51, 52, 61, 62, 63, 64, 65, 71, 72, 75, 81, 82, 84, 85, 91, 92, 93, 95, 96}
    return m in good_2d

def is_good_3d(m):
    # m is a 3-digit number with distinct nonzero digits.
    s_m = str(m)
    digits = list(s_m)

    for i in range(3):
        # Construct m' by removing digit at index i
        m_prime_str = "".join(digits[:i] + digits[i+1:])
        m_prime = int(m_prime_str)

        # Check divisibility: m' must divide m
        if m % m_prime == 0:
            # m' must be good. Since m' is 2-digit (because m is 3-digit), we check the 2D list.
            if m_prime >= 10:
                if is_good_2d(m_prime):
                    return True
            # (We established m' cannot be 1-digit here, as m starts with 9 and has distinct digits)

    return False

# Check numbers from 987 down to 975
print("Checking numbers > 975:")
for m in range(987, 975, -1):
    # Filter to ensure digits are distinct and nonzero (redundant if we only check 987 down to 975, 
    # but good practice if the range were wider)
    s_m = str(m)
    if len(set(s_m)) != len(s_m) or '0' in s_m:
        continue # Should not happen in this specific range but safety first

    if not is_good_3d(m):
        print(f"Confirmed NOT GOOD: {m}")
    else:
        print(f"Found GOOD: {m}")
        # If we find a good number here, it means 975 is not the largest.
